    double sum_p = 0.0;
    double v[3];
    double r[3];
    double t[3];
    int i;

    if (temperature == NULL || voltage == NULL || resistance == NULL ||
        next_temperature == NULL || current == NULL || power == NULL ||
        total_power == NULL) {
        return ADCS_E_NULL;
    }

    if ((!adcs_is_finite_vec3(temperature)) || (!adcs_is_finite_vec3(voltage)) ||
        (!adcs_is_finite_vec3(resistance)) || (!isfinite(ambient)) ||
        (!isfinite(thermal_capacity)) || (!isfinite(thermal_resistance)) ||
        (!isfinite(dt)) ||
        (thermal_capacity <= 0.0) || (thermal_resistance <= 0.0) || (dt < 0.0)) {
        return ADCS_E_RANGE;
    }

    v[0] = voltage->x;
    v[1] = voltage->y;
    v[2] = voltage->z;
    r[0] = resistance->x;
    r[1] = resistance->y;
    r[2] = resistance->z;
    t[0] = temperature->x;
    t[1] = temperature->y;
    t[2] = temperature->z;

    if ((r[0] <= 0.0) || (r[1] <= 0.0) || (r[2] <= 0.0)) {
        return ADCS_E_RANGE;
    }

    for (i = 0; i < 3; i++) {
        double p_i = v[i] * v[i] / r[i];
        double i_i = v[i] / r[i];
        double t_next = t[i] + dt * (p_i - (t[i] - ambient) / thermal_resistance) / thermal_capacity;
        if (i == 0) {
            current->x = i_i;
            power->x = p_i;
            next_temperature->x = t_next;
        } else if (i == 1) {
            current->y = i_i;
            power->y = p_i;
            next_temperature->y = t_next;
        } else {
            current->z = i_i;
            power->z = p_i;
            next_temperature->z = t_next;
        }
        sum_p += p_i;
    }

    *total_power = sum_p;
    return ADCS_OK;
}

